        example: 'Для класса несовершеннолетних <span class="mark-yellow">(0-17 лет)</span> границами являются 0 и 17.<br><br>Используя метод 3-х значений, вы проверяете:<ul><li>Значение перед границей: <span class="mark-red">-1</span></li><li>Саму границу: <span class="mark-green">0</span></li><li>Значение после границы: <span class="mark-green">1</span></li><li>Значение перед верхней границей: <span class="mark-green">16</span></li><li>Саму верхнюю границу: <span class="mark-green">17</span></li><li>Значение после неё: <span class="mark-red">18</span></li></ul>Для поля с десятичными дробями, например, от 0.01 до 10.00 включительно, границы будут: для нижней — 0.00, 0.01, 0.02; для верхней — 9.99, 10.00, 10.01.',
