        example: 'В инструменте <span class="mark-yellow">PICT (Pairwise Independent Combinatorial Testing)</span> вы описываете все параметры и их значения, а инструмент автоматически генерирует минимальный набор тестов, который покрывает все возможные пары.<br><br>Для параметров:<ul><li>Размер: <span class="mark-yellow">M, L</span></li><li>Тесто: <span class="mark-yellow">тонкое, толстое</span></li><li>Начинка: <span class="mark-yellow">сырная, мясная, овощная</span></li></ul>PICT сгенерирует <span class="mark-green">4-6 тестов</span> вместо <span class="mark-red">12</span>.',
