        example: '<span class="mark-purple">Что проверять при тестировании API:</span><ol><li><span class="mark-purple">Обязательные/необязательные поля</span> — email обязателен, phone — нет</li><li><span class="mark-purple">Типы данных</span> — числа, строки, массивы</li><li><span class="mark-purple">Статус-коды:</span><ul><li><span class="mark-purple">200</span> — успех</li><li><span class="mark-purple">400</span> — плохой запрос</li><li><span class="mark-purple">401</span> — не авторизован</li><li><span class="mark-purple">403</span> — нет прав</li><li><span class="mark-purple">404</span> — ресурс не найден</li><li><span class="mark-purple">500</span> — ошибка сервера</li></ul></li><li><span class="mark-purple">Ответ от сервера</span> — заголовки, тело, все ключи и значения</li><li><span class="mark-purple">Авторизация и разрешения</span></li><li><span class="mark-purple">Время ответа</span> — если 10 секунд — проблема</li></ol>',
        academic: '<span class="mark-purple">Как тестировать API:</span> <ol><li>Запросить документацию (WSDL для SOAP, Swagger для REST).</li><li>Изучить методы.</li><li>Создать коллекции в Postman.</li><li>Запустить тестирование.</li></ol> <span class="mark-purple">Проверять:</span> <ul><li>обязательные/необязательные значения</li><li>типы данных</li><li>статус-коды</li><li>ответ сервера</li><li>авторизация</li><li>время ответа</li></ul>',
        source: 'API.docx',
        meta: ['Postman', 'SoapUI', 'Тестирование']
