        example: '<span class="mark-orange">Ошибки и правильное написание в XML:</span><table border="1" cellpadding="4"><tr><th>Ошибка</th><th>Правильно</th></tr><tr><td><code>&lt;tag1&gt;&lt;/tag1&gt;&lt;tag2&gt;&lt;/tag2&gt;</code> (нет корня)</td><td><code>&lt;root&gt;&lt;tag1&gt;&lt;/tag1&gt;&lt;tag2&gt;&lt;/tag2&gt;&lt;/root&gt;</code></td></tr><tr><td><code>&lt;tag&gt;Text&lt;tag&gt;</code> (не закрыт)</td><td><code>&lt;tag&gt;Text&lt;/tag&gt;</code></td></tr><tr><td><code>&lt;Tag&gt;example&lt;/tag&gt;</code> (регистр)</td><td><code>&lt;tag&gt;example&lt;/tag&gt;</code></td></tr><tr><td><code>&lt;b&gt;&lt;i&gt;Text&lt;/b&gt;&lt;/i&gt;</code> (вложение)</td><td><code>&lt;b&gt;&lt;i&gt;Text&lt;/i&gt;&lt;/b&gt;</code></td></tr><tr><td><code>&lt;tag attribute=value&gt;</code> (нет кавычек)</td><td><code>&lt;tag attribute="value"&gt;</code></td></tr><tr><td><code>&lt;tag&gt;5 &lt; 10&lt;/tag&gt;</code></td><td><code>&lt;tag&gt;5 &amp;lt; 10&lt;/tag&gt;</code></td></tr></table>',
