        term: 'Метод 2-х и 3-х значений',
        category: 'interview_testdesign',
        tag: 'Собеседование',
        tagColor: 'orange',
        simple: 'Варианты анализа граничных значений. Метод 2-х значений проверяет саму границу и значение за ней. Метод 3-х значений — значение перед границей, саму границу и значение после.',
        example: 'Для границы 17 в поле возраста (0-120):<br><br><span class="mark-orange">Метод 2-х значений:</span><ul><li>17 (сама граница)</li><li>18 (значение за границей)</li></ul><br><span class="mark-orange">Метод 3-х значений:</span><ul><li>16 (значение перед границей)</li><li>17 (сама граница)</li><li>18 (значение после границы)</li></ul><br>Для нижней границы 0:<br><span class="mark-orange">Метод 2-х значений:</span> 0 и -1<br><span class="mark-orange">Метод 3-х значений:</span> -1, 0, 1<br><br>Метод 3-х значений считается более надежным, но требует больше тестов.',
